            _, oid = order

            if oid not in order_state:
                continue

            price, qty_remaining, arr_idx, status = order_state[oid]

            if status != 'resting':
                continue

            # Remove from book
            if price is not None:
                if oid in [o[0] for o in buy_book.get(price, [])]:
                    buy_book[price] = [(o_id, o_qty, o_arr) for o_id, o_qty, o_arr in buy_book[price] if o_id != oid]
                    if not buy_book[price]:
                        del buy_book[price]
                elif oid in [o[0] for o in sell_book.get(price, [])]:
                    sell_book[price] = [(o_id, o_qty, o_arr) for o_id, o_qty, o_arr in sell_book[price] if o_id != oid]
                    if not sell_book[price]:
                        del sell_book[price]

            order_state[oid] = (price, 0, arr_idx, 'cancelled')

    return trades
